export interface AdAccountsAudience {

  /** Ad account ID. */
  ad_account_id?: string;

  /** [Audience types](/docs/reference/glossary/#Audience Types): ACTALIKE, ENGAGEMENT, CUSTOMER_LIST and VISITOR */
  audience_type?: {

  };

  /** The company that created this audience. */
  created_by_company_name?: string;

  /** Creation time. Unix timestamp in seconds. */
  created_timestamp?: number;

  /** Audience description. */
  description?: string;

  /** Audience ID. */
  id: string;

  /** Whether the audience derives from a new customer acquisition (expanded matching) customer list. Read-only. */
  is_nca?: boolean;

  /** Audience name. */
  name?: string;

  /** JSON object defining targeted audience users. Example rule formats per audience type:
CUSTOMER_LIST: { "customer_list_id": "<customer list ID>"}
ACTALIKE: { "seed_id": ["<audience ID>"], "country": "US", "percentage": "10" }
(Valid countries include: "US", "CA", and "GB". Percentage should be 1-10.
The targeted audience should be this % size across Pinterest.)
VISITOR: { "visitor_source_id": ["<conversion tag ID>"], "retention_days": "180", "event_source": {"=": ["web", "mobile"]}, "ingestion_source": {"=": ["tag"]}}
(Retention days should be 1-540. Retention applies to specific customers.)
ENGAGEMENT: {"engagement_domain": ["www.example.com"], "engager_type": 1}
Learn more about [engagement audiences](/docs/work-with-targets-and-audiences/create-audiences/#engagement-audience). */
  rule?: {
    ad_account_id?: string;
    ad_id?: string[];
    campaign_id?: string[];
    country?: string;
    customer_list_id?: string;
    engagement_domain?: string[];
    engagement_type?: string;
    engager_type?: number;
    event?: string;
    event_data?: {
      currency?: {

      };
      lead_type?: string;
      line_items?: {
        product_brand?: string;
        product_category?: string;
        product_id?: number;
        product_name?: string;
        product_price?: string;
        product_quantity?: number;
        product_variant?: string;
        product_variant_id?: string;
      };
      order_id?: string;
      order_quantity?: number;
      page_name?: string;
      promo_code?: string;
      property?: string;
      search_query?: string;
      value?: string;
      video_title?: string;
    };
    event_source?: {

    };
    ingestion_source?: {

    };
    objective_type?: "AWARENESS" | "CONSIDERATION" | "WEB_CONVERSION" | "CATALOG_SALES" | "VIDEO_COMPLETION" | "SALES"[];
    percentage?: string | number;
    pin_id?: string[];
    prefill?: boolean;
    retention_days?: number;
    seed_id?: number[] | string[];
    url?: string[];
    visitor_source_id?: string | string[];
  };

  /** Audience size. */
  size?: number;

  /** Audience status. READY, INITIALIZING, TOO_SMALL - Each audience list needs to have at least 100 people with Pinterest accounts before you can start using it. */
  status?: {

  };

  /** Always "audience". */
  type?: string;

  /** Last update time. Unix timestamp in seconds. */
  updated_timestamp?: number;
}

