export interface AdsAnalyticsCreateAsyncResponse {

  message?: string;

  /** Possible status for a bulk reporting job */
  report_status?: "DOES_NOT_EXIST" | "FINISHED" | "IN_PROGRESS" | "EXPIRED" | "FAILED" | "CANCELLED";

  token?: string;
}

export type AdsAnalyticsFilterColumn = "SPEND_IN_DOLLAR" | "TOTAL_IMPRESSION";

export type AdsAnalyticsFilterOperator = "LESS_THAN" | "GREATER_THAN";

export interface AdsAnalyticsGetAsyncResponse {

  /** Possible status for a bulk reporting job */
  report_status?: "DOES_NOT_EXIST" | "FINISHED" | "IN_PROGRESS" | "EXPIRED" | "FAILED" | "CANCELLED";

  size?: number;

  url?: string;
}

export interface AdsAnalyticsMetricsFilter {

  /** Reporting columns for sync reporting data filter */
  field: "SPEND_IN_DOLLAR" | "TOTAL_IMPRESSION";

  /** Filter operator for sync reporting */
  operator: "LESS_THAN" | "GREATER_THAN";

  /** List of values for filtering */
  values: number[];
}

export interface AdsCreditDiscountsResponse {

  /** True if the offer code is currently active. */
  active?: boolean;

  /** Advertiser ID the offer was applied to. */
  advertiser_id?: string;

  /** Currency value for the discount. */
  discountCurrency?: string;

  /** The discount applied in the offer's currency value. */
  discountInMicroCurrency?: number;

  /** The type of discount of this credit */
  discountType?: {

  };

  /** The credits left to spend. */
  remainingDiscountInMicroCurrency?: number;

  /** Human readable title of the offer code. */
  title?: string;
}

export type AdsCreditDiscountType = string;

export interface AdsCreditRedeem {

  /** Error code type if error occurs */
  errorCode?: number;

  /** Reason for failure */
  errorMessage?: string;

  /** Returns true if the offer code was successfully applied(validateOnly=false) or can be applied(validateOnly=true). */
  success?: boolean;
}

export interface AdsCreditRedeemCreate {

  /** Takes in a SHA256 hash of the offerCode. */
  offerCodeHash: string;

  /** If true, only validate if we can redeem offer code. Otherwise it will actually apply the offer code to the account */
  validateOnly: boolean;
}

