export interface ProductGroupPromotion {

  /** ID of the ad group the product group belongs to. */
  ad_group_id?: string;

  /** The bid in micro currency. */
  bid_in_micro_currency?: number;

  /** ID of the catalogs product group that this product group promotion references (required for create operations) */
  catalog_product_group_id?: string;

  /** Catalogs product group name */
  catalog_product_group_name?: string;

  /** Collections ad header type */
  collections_header_type?: string;

  /** Collections Hero Destination Url */
  collections_hero_destination_url?: string;

  /** Hero Pin ID if this PG is promoted as a Collection */
  collections_hero_pin_id?: string;

  /** Ad creative type enum.
**Note:** SHOP_THE_PIN has been deprecated. Please use COLLECTION instead. */
  creative_type?: "REGULAR" | "VIDEO" | "SHOPPING" | "CAROUSEL" | "MAX_VIDEO" | "SHOP_THE_PIN" | "COLLECTION" | "IDEA" | "SHOWCASE" | "QUIZ" | "COLLAGE" | "MAX_WIDTH_REGULAR_COLLECTION" | "MAX_WIDTH_VIDEO_COLLECTION" | "APP";

  /** Select a call to action (CTA) to display below your ad. CTA options for catalog sales campaigns are SHOP_NOW, BOOK_NOW, ON_SALE, GET_DEAL, BUY_ONLINE_PICKUP_IN_STORE */
  customizable_cta_type?: "GET_OFFER" | "LEARN_MORE" | "ORDER_NOW" | "SHOP_NOW" | "SIGN_UP" | "SUBSCRIBE" | "BUY_NOW" | "CONTACT_US" | "GET_QUOTE" | "VISIT_SITE" | "APPLY_NOW" | "BOOK_NOW" | "REGISTER_NOW" | "FIND_A_DEALER" | "WATCH_NOW" | "READ_MORE" | "BUY_TICKETS" | "DONATE_NOW" | "DOWNLOAD" | "EXPLORE_MORE" | "FIND_A_LOCATION" | "GET_DEAL" | "GET_RECIPE" | "GET_SHOWTIMES" | "ON_SALE" | "PLAY_GAME" | "TRY_IT" | "BUY_ONLINE_PICKUP_IN_STORE" | "SHOP_ON_ADVERTISER" | "SHOP_THE_COLLECTION" | "GET_IT_NOW" | "TAKE_A_PEEK" | "TAKE_A_CLOSER_LOOK";

  /** The full product group definition path */
  definition?: string;

  /** Where a user is taken after clicking on an ad in grid.

**Note:**  This parameter is read-only and is set to `DIRECT_TO_DESTINATION` by default for direct links supported ads. `grid_click_type` values provided will be ignored. */
  grid_click_type?: "CLOSEUP" | "DIRECT_TO_DESTINATION";

  /** ID of the product group promotion (required for update operations). */
  id?: string;

  /** True if the group is BIDDABLE, false if it should be EXCLUDED from serving ads. */
  included?: boolean;

  /** Enable generate backgrounds for the product group, default value is FALSE. When enabled, Pinterest will use generative AI to apply backgrounds for your product images that help drive user inspiration and engagement. */
  is_generate_background?: boolean;

  /** Set to `TRUE` to automatically resize your product images with generative AI. This ensures that images have optimal appearance for better performance. */
  is_image_auto_resizing?: boolean;

  /** If set to true products promoted in this product group will use the Mobile Deep Link specified in your catalog */
  is_mdl?: boolean;

  /** The parent Product Group ID of this Product Group */
  parent_id?: string;

  /** Select whether to promote the image or video pin by default for items in the promoted product group. If selecting IMAGE, image will be promoted for all ads in the product group, and when selecting VIDEO, video will be promoted when present, otherwise fall back to image. This is applicable for standard shopping ads only. */
  preferred_media_type?: string;

  /** The definition of the product group, relative to its parent - an attribute name/value pair */
  relative_definition?: string;

  /** The ad image tag selected for the product group promotion. */
  selected_image_tag?: string;

  /** The ad video tag selected for the product group promotion. */
  selected_video_tag?: string;

  /** Slideshow Collections Description */
  slideshow_collections_description?: string;

  /** Slideshow Collections Title */
  slideshow_collections_title?: string;

  /** Entity status */
  status?: "ACTIVE" | "PAUSED" | "ARCHIVED" | "DRAFT" | "DELETED_DRAFT";

  /** Tracking template for proudct group promotions. 4000 limit */
  tracking_url?: string;
}

